// Requirement: cloud-drive (docs/requirements/2026-10-19-cloud-drive.md)
// Task: 2 (batch-backfill-drive)
// Generated by: sean run
// Catalog: docs/artifacts/2026-10-19-cloud-drive.md
//
// Idempotent safety-net batch: folds v1 top-level drive data (keyed by the old
// `driveType` + `ownerId` model) into `type = 'drive'` spaces. The old
// `driveType`/`ownerId` columns are still present (dropped later in migration
// 20261019T100000), so this script reads them.
//
// Production has no v1 data, so this usually need not run. It supports
// `--dry-run` (preview) and `--verify` (assert no orphan rows remain).
import { Kysely, sql } from 'kysely';
import { createHash } from 'node:crypto';

export type DriveRow = {
  workspaceId: string;
  driveType: 'personal' | 'shared';
  ownerId: string | null;
  id: string;
  kind: 'folder' | 'file';
};

export type DriveUnit = {
  key: string;
  workspaceId: string;
  driveType: 'personal' | 'shared';
  ownerId: string | null;
  memberUserIds: string[];
  folderIds: string[];
  fileIds: string[];
};

export type SpaceInsert = {
  id: string;
  workspaceId: string;
  name: string;
  slug: string;
  type: string;
  creatorId: string | null;
  defaultRole: string;
  visibility: string;
  isPersonal: boolean;
};

export type MemberInsert = { spaceId: string; userId: string; role: string };

export type UnitPlan = {
  spaceId: string;
  driveType: 'personal' | 'shared';
  space: SpaceInsert;
  members: MemberInsert[];
};

/**
 * Deterministic UUID v4 derived from a key. Stable across runs, so re-running
 * the backfill produces the same space id -> idempotent upsert.
 */
export function deterministicUuid(key: string): string {
  const h = createHash('sha256').update(`drive-backfill:${key}`).digest();
  const b = Buffer.from(h.subarray(0, 16));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  const hex = b.toString('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(
    16,
    20,
  )}-${hex.slice(20, 32)}`;
}

export function groupDriveUnits(rows: DriveRow[]): DriveUnit[] {
  const map = new Map<string, DriveUnit>();
  for (const r of rows) {
    const key = `${r.driveType}:${r.workspaceId}:${r.ownerId ?? 'shared'}`;
    let u = map.get(key);
    if (!u) {
      u = {
        key,
        workspaceId: r.workspaceId,
        driveType: r.driveType,
        ownerId: r.ownerId,
        memberUserIds: [],
        folderIds: [],
        fileIds: [],
      };
      map.set(key, u);
    }
    if (r.kind === 'folder') u.folderIds.push(r.id);
    else u.fileIds.push(r.id);
  }
  return [...map.values()];
}

export function buildSpaceRow(unit: DriveUnit, spaceId: string): SpaceInsert {
  const isPersonal = unit.driveType === 'personal';
  return {
    id: spaceId,
    workspaceId: unit.workspaceId,
    name: isPersonal ? 'My Drive' : 'Shared Drive',
    slug: `drive-${spaceId.slice(0, 8)}`,
    type: 'drive',
    creatorId: unit.ownerId,
    defaultRole: 'reader',
    visibility: isPersonal ? 'private' : 'workspace',
    isPersonal: false,
  };
}

function buildMembers(unit: DriveUnit, spaceId: string): MemberInsert[] {
  if (unit.driveType === 'personal') {
    return unit.ownerId
      ? [{ spaceId, userId: unit.ownerId, role: 'admin' }]
      : [];
  }
  return unit.memberUserIds.map((userId) => ({
    spaceId,
    userId,
    role: 'reader',
  }));
}

export function buildOperations(units: DriveUnit[]): UnitPlan[] {
  return units.map((u) => {
    const spaceId = deterministicUuid(`drive-space:${u.key}`);
    return {
      spaceId,
      driveType: u.driveType,
      space: buildSpaceRow(u, spaceId),
      members: buildMembers(u, spaceId),
    };
  });
}

/**
 * Shared drives are scoped to a workspace; resolve their members from the
 * workspace's root space (earliest non-personal space). No-op when none found.
 */
async function resolveSharedMembers(
  db: Kysely<any>,
  units: DriveUnit[],
): Promise<DriveUnit[]> {
  for (const u of units) {
    if (u.driveType !== 'shared') continue;
    const root = await db
      .selectFrom('spaces')
      .select('id')
      .where('workspaceId', '=', u.workspaceId)
      .where('isPersonal', '=', false)
      .orderBy('createdAt', 'asc')
      .limit(1)
      .executeTakeFirst();
    if (!root) continue;
    const members = await db
      .selectFrom('space_members')
      .select('userId')
      .where('spaceId', '=', (root as any).id)
      .where('userId', 'is not', null)
      .execute();
    u.memberUserIds = members
      .map((m: any) => m.userId)
      .filter(Boolean) as string[];
  }
  return units;
}

export type BackfillResult = {
  spacesCreated: number;
  membersAdded: number;
  foldersAssigned: number;
  filesAssigned: number;
  sharesAssigned: number;
  versionsAssigned: number;
  dryRun: boolean;
};

/**
 * Read v1 drive rows lacking a `spaceId`, group them into drive-space units,
 * then upsert the spaces + members and backfill `spaceId` on every drive table.
 * Idempotent: deterministic space ids + `ON CONFLICT DO NOTHING` + scoped
 * `WHERE spaceId IS NULL` updates.
 */
export async function applyBackfill(
  db: Kysely<any>,
  opts: { dryRun?: boolean; verify?: boolean } = {},
): Promise<BackfillResult> {
  const dryRun = opts.dryRun ?? false;

  const folders = await db
    .selectFrom('drive_folders')
    .selectAll()
    .where('spaceId', 'is', null)
    .execute();
  const files = await db
    .selectFrom('drive_files')
    .selectAll()
    .where('spaceId', 'is', null)
    .execute();

  const rows: DriveRow[] = [
    ...folders.map((f: any) => ({
      workspaceId: f.workspaceId,
      driveType: f.driveType,
      ownerId: f.ownerId,
      id: f.id,
      kind: 'folder' as const,
    })),
    ...files.map((f: any) => ({
      workspaceId: f.workspaceId,
      driveType: f.driveType,
      ownerId: f.ownerId,
      id: f.id,
      kind: 'file' as const,
    })),
  ];

  let units = groupDriveUnits(rows);
  units = await resolveSharedMembers(db, units);
  const plans = buildOperations(units);

  if (dryRun) {
    return {
      spacesCreated: plans.length,
      membersAdded: plans.reduce((n, p) => n + p.members.length, 0),
      foldersAssigned: rows.filter((r) => r.kind === 'folder').length,
      filesAssigned: rows.filter((r) => r.kind === 'file').length,
      sharesAssigned: 0,
      versionsAssigned: 0,
      dryRun: true,
    };
  }

  let spacesCreated = 0;
  let membersAdded = 0;
  let foldersAssigned = 0;
  let filesAssigned = 0;
  let sharesAssigned = 0;
  let versionsAssigned = 0;

  for (const plan of plans) {
    await db
      .insertInto('spaces')
      .values(plan.space)
      .onConflict((oc) => oc.doNothing())
      .execute();
    spacesCreated += 1;

    for (const m of plan.members) {
      await db
        .insertInto('space_members')
        .values({
          id: deterministicUuid(`member:${plan.spaceId}:${m.userId}`),
          spaceId: m.spaceId,
          userId: m.userId,
          role: m.role,
          addedById: null,
        })
        .onConflict((oc) => oc.doNothing())
        .execute();
      membersAdded += 1;
    }

    const ownerPred = plan.space.creatorId
      ? (eb: any) =>
          eb.and([
            eb('driveType', '=', plan.driveType),
            eb('ownerId', '=', plan.space.creatorId),
          ])
      : (eb: any) =>
          eb.and([
            eb('driveType', '=', plan.driveType),
            eb('ownerId', 'is', null),
          ]);

    const fRes = await db
      .updateTable('drive_folders')
      .set({ spaceId: plan.spaceId })
      .where('workspaceId', '=', plan.space.workspaceId)
      .where(ownerPred)
      .where('spaceId', 'is', null)
      .executeTakeFirst();
    foldersAssigned += Number((fRes as any)?.numUpdatedRows ?? 0);

    const fiRes = await db
      .updateTable('drive_files')
      .set({ spaceId: plan.spaceId })
      .where('workspaceId', '=', plan.space.workspaceId)
      .where(ownerPred)
      .where('spaceId', 'is', null)
      .executeTakeFirst();
    filesAssigned += Number((fiRes as any)?.numUpdatedRows ?? 0);

    const sRes = await sql`UPDATE drive_shares ds SET space_id = ${plan.spaceId} FROM drive_files df WHERE ds.file_id = df.id AND df.space_id = ${plan.spaceId}`.execute(
      db,
    );
    sharesAssigned += Number((sRes as any)?.numUpdatedRows ?? 0);

    const vRes = await sql`UPDATE drive_file_versions dv SET space_id = ${plan.spaceId} FROM drive_files df WHERE dv.file_id = df.id AND df.space_id = ${plan.spaceId}`.execute(
      db,
    );
    versionsAssigned += Number((vRes as any)?.numUpdatedRows ?? 0);
  }

  if (opts.verify) {
    const orphan = await db
      .selectFrom('drive_folders')
      .select((eb) => eb.fn.count('id').as('c'))
      .where('spaceId', 'is', null)
      .executeTakeFirst();
    if (Number((orphan as any)?.c ?? 0) > 0) {
      throw new Error(
        `verify failed: ${(orphan as any).c} drive_folders still have null spaceId`,
      );
    }
  }

  return {
    spacesCreated,
    membersAdded,
    foldersAssigned,
    filesAssigned,
    sharesAssigned,
    versionsAssigned,
    dryRun: false,
  };
}
